function UploadScreen({onNav,onFileReady}){
  const[dragging,setDragging]=useState(false);const[file,setFile]=useState(null);const[err,setErr]=useState('');const fileRef=useRef();
  const validate=(f)=>{if(!f)return'No file selected';const ext='.'+f.name.split('.').pop().toLowerCase();if(!ALLOWED_EXT.includes(ext))return`File type not supported. Allowed: ${ALLOWED_EXT.join(', ')}`;if(f.size>MAX_MB*1024*1024)return`File too large. Maximum size is ${MAX_MB} MB`;return null;};
  const pick=(f)=>{setErr('');const e=validate(f);if(e){setErr(e);return;}setFile(f);};
  const onDrop=(e)=>{e.preventDefault();setDragging(false);pick(e.dataTransfer.files[0]);};
  const proceed=()=>{if(!file){setErr('Please select a document first');return;}onFileReady(file);onNav('newjob');};
  return(<div style={css.page}><BackBtn onClick={()=>onNav('home')}/><div style={{display:'flex',alignItems:'center',gap:8,marginBottom:24}}><div style={{display:'flex',alignItems:'center',gap:6}}><div style={{width:26,height:26,borderRadius:13,background:G.greenDark,display:'flex',alignItems:'center',justifyContent:'center',fontSize:12,fontWeight:800,color:'#fff'}}>1</div><span style={{fontSize:13,color:G.green,fontWeight:700}}>Upload</span></div><div style={{flex:1,height:1,background:G.border2}}/><div style={{display:'flex',alignItems:'center',gap:6}}><div style={{width:26,height:26,borderRadius:13,background:G.card2,border:`1px solid ${G.border2}`,display:'flex',alignItems:'center',justifyContent:'center',fontSize:12,fontWeight:800,color:G.text3}}>2</div><span style={{fontSize:13,color:G.text3,fontWeight:600}}>Preferences</span></div></div><div style={css.pageTitle}>Upload document</div><div onDragEnter={e=>{e.preventDefault();setDragging(true);}}onDragOver={e=>{e.preventDefault();setDragging(true);}}onDragLeave={e=>{e.preventDefault();setDragging(false);}}onDrop={onDrop}onClick={()=>!file&&fileRef.current?.click()}style={{border:`2px dashed ${dragging?G.green:file?G.greenBdr:G.border2}`,borderRadius:20,background:dragging?'#061A0E':file?'#081A10':G.card,padding:file?'28px 24px':'48px 24px',textAlign:'center',cursor:file?'default':'pointer',marginBottom:12}}><input ref={fileRef}type="file"accept={ALLOWED_EXT.join(',')}style={{display:'none'}}onChange={e=>pick(e.target.files[0])}/>{!file?(<><div style={{fontSize:56,marginBottom:16}}>{dragging?'📂':'📁'}</div><div style={{fontSize:18,fontWeight:700,color:dragging?G.green:G.text,marginBottom:8}}>{dragging?'Drop it here!':'Drag & drop your document'}</div><div style={{fontSize:13,color:G.text3,marginBottom:24}}>or tap the button below to browse</div><div style={{display:'inline-flex',gap:6,flexWrap:'wrap',justifyContent:'center',marginBottom:12}}>{['PDF','DOCX','DOC','JPG','PNG'].map(t=>(<span key={t}style={{background:G.card2,border:`1px solid ${G.border2}`,borderRadius:6,padding:'4px 10px',fontSize:11,fontWeight:700,color:G.text3}}>{t}</span>))}</div><div style={{fontSize:11,color:G.text3}}>Max {MAX_MB} MB</div></>):(<><div style={{fontSize:48,marginBottom:10}}>{getFileIcon(file.name)}</div><div style={{fontSize:15,fontWeight:700,color:G.green,marginBottom:4,wordBreak:'break-all',padding:'0 8px'}}>{file.name}</div><div style={{fontSize:12,color:G.text3,marginBottom:18}}>{fmtSize(file.size)}</div><div style={{display:'flex',gap:10,justifyContent:'center'}}><button onClick={e=>{e.stopPropagation();setFile(null);setErr('');}}style={{background:G.redBg,border:`1px solid ${G.redBdr}`,color:G.red,borderRadius:8,padding:'8px 16px',fontSize:13,fontWeight:600,cursor:'pointer'}}>✕ Remove</button><button onClick={e=>{e.stopPropagation();fileRef.current?.click();}}style={{background:G.card2,border:`1px solid ${G.border2}`,color:G.text2,borderRadius:8,padding:'8px 16px',fontSize:13,fontWeight:600,cursor:'pointer'}}>Change</button></div></>)}</div>{!file&&(<button style={{...css.btnGhost,marginBottom:12}}onClick={()=>fileRef.current?.click()}>📂 Browse files from device</button>)}<Alert msg={err}/><div style={{...css.card2,marginTop:8,marginBottom:16}}><div style={{fontSize:11,fontWeight:700,color:G.text3,textTransform:'uppercase',letterSpacing:0.8,marginBottom:12}}>Supported file types</div><div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:10}}>{[{fmt:'PDF',icon:'📕',note:'All versions'},{fmt:'DOCX / DOC',icon:'📘',note:'Word documents'},{fmt:'JPG / JPEG',icon:'🖼️',note:'Photos & scans'},{fmt:'PNG',icon:'🖼️',note:'Images'}].map(r=>(<div key={r.fmt}style={{display:'flex',alignItems:'center',gap:8}}><span style={{fontSize:18}}>{r.icon}</span><div><div style={{fontSize:12,fontWeight:600,color:G.text}}>{r.fmt}</div><div style={{fontSize:11,color:G.text3}}>{r.note}</div></div></div>))}</div></div><button style={{...css.btn,opacity:file?1:0.4}}onClick={proceed}disabled={!file}>{file?'Continue to preferences →':'Select a file to continue'}</button></div>);
