// ── PAGE SELECTOR ─────────────────────────────────────────────────────────────
function PageSelector({onPagesChange}){
  const[mode,setMode]=useState('all');
  const[singlePage,setSinglePage]=useState('');
  const[rangeFrom,setRangeFrom]=useState('');
  const[rangeTo,setRangeTo]=useState('');
  const[customStr,setCustomStr]=useState('');
  const[parseErr,setParseErr]=useState('');

  const parseCustom=(str)=>{
    if(!str.trim())return{pages:[],err:'Enter at least one page'};
    const parts=str.split(',').map(s=>s.trim()).filter(Boolean);
    const pageSet=new Set();
    for(const part of parts){
      if(/^\d+$/.test(part)){const n=parseInt(part);if(n<1)return{pages:[],err:`Page number must be ≥ 1 (got ${n})`};pageSet.add(n);}
      else if(/^\d+-\d+$/.test(part)){const[a,b]=part.split('-').map(Number);if(a<1)return{pages:[],err:'Start of range must be ≥ 1'};if(b<a)return{pages:[],err:`End of range (${b}) must be ≥ start (${a})`};if(b-a>999)return{pages:[],err:'Range too large (max 1000 pages per range)'};for(let i=a;i<=b;i++)pageSet.add(i);}
      else return{pages:[],err:`"${part}" is not valid — use numbers like 1,3 or ranges like 5-8`};
    }
    return{pages:[...pageSet].sort((a,b)=>a-b),err:null};
  };

  useEffect(()=>{
    setParseErr('');
    if(mode==='all'){onPagesChange(1,'all');return;}
    if(mode==='single'){const n=parseInt(singlePage);if(!singlePage||isNaN(n)||n<1){onPagesChange(0,'');return;}onPagesChange(1,String(n));return;}
    if(mode==='range'){const f=parseInt(rangeFrom),t=parseInt(rangeTo);if(!rangeFrom||!rangeTo||isNaN(f)||isNaN(t)){onPagesChange(0,'');return;}if(f<1){setParseErr('Start page must be ≥ 1');onPagesChange(0,'');return;}if(t<f){setParseErr(`End page (${t}) must be ≥ start (${f})`);onPagesChange(0,'');return;}onPagesChange(t-f+1,`${f}-${t}`);return;}
    if(mode==='custom'){const{pages,err}=parseCustom(customStr);if(err){setParseErr(err);onPagesChange(0,'');return;}if(pages.length===0){onPagesChange(0,'');return;}onPagesChange(pages.length,pages.join(','));}
  // eslint-disable-next-line
  },[mode,singlePage,rangeFrom,rangeTo,customStr]);

  const inp={...css.input,fontSize:16,fontWeight:700};
  const modes=[{id:'all',label:'📄 All pages'},{id:'single',label:'1️⃣ Single page'},{id:'range',label:'📑 Page range'},{id:'custom',label:'✏️ Custom'}];

  return(
    <div>
      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:8,marginBottom:14}}>
        {modes.map(m=>{const active=mode===m.id;return(<button key={m.id}onClick={()=>{setMode(m.id);setParseErr('');}}style={{padding:'10px 12px',borderRadius:8,border:`1.5px solid ${active?G.green:G.border2}`,background:active?G.greenBg:G.card2,color:active?G.green:G.text2,cursor:'pointer',fontWeight:600,fontSize:12,textAlign:'left'}}>{m.label}</button>);})}
      </div>

      {mode==='all'&&(<div style={{fontSize:13,color:G.text3,padding:'4px 2px',lineHeight:1.6}}>The entire document will be printed from first to last page.</div>)}

      {mode==='single'&&(
        <div>
          <input style={inp}type="number"inputMode="numeric"min="1"placeholder="Enter page number  e.g. 5"value={singlePage}onChange={e=>setSinglePage(e.target.value.replace(/\D/g,''))}/>
          {singlePage&&parseInt(singlePage)>=1&&(<div style={{fontSize:12,color:'#4ADE80',marginTop:6}}>Printing page {singlePage} only</div>)}
        </div>
      )}

      {mode==='range'&&(
        <div>
          <div style={{display:'flex',gap:12,alignItems:'center'}}>
            <div style={{flex:1}}>
              <div style={{fontSize:11,color:G.text3,marginBottom:4}}>From page</div>
              <input style={{...inp,boxSizing:'border-box'}}type="number"inputMode="numeric"min="1"placeholder="e.g. 3"value={rangeFrom}onChange={e=>setRangeFrom(e.target.value.replace(/\D/g,''))}/>
            </div>
            <div style={{fontSize:18,color:G.text3,marginTop:18}}>→</div>
            <div style={{flex:1}}>
              <div style={{fontSize:11,color:G.text3,marginBottom:4}}>To page</div>
              <input style={{...inp,boxSizing:'border-box'}}type="number"inputMode="numeric"min="1"placeholder="e.g. 10"value={rangeTo}onChange={e=>setRangeTo(e.target.value.replace(/\D/g,''))}/>
            </div>
          </div>
          {rangeFrom&&rangeTo&&parseInt(rangeTo)>=parseInt(rangeFrom)&&!parseErr&&(
            <div style={{fontSize:12,color:'#4ADE80',marginTop:8}}>Printing pages {rangeFrom} to {rangeTo} · {parseInt(rangeTo)-parseInt(rangeFrom)+1} pages total</div>
          )}
        </div>
      )}

      {mode==='custom'&&(
        <div>
          <input style={inp}placeholder="e.g. 1, 3, 5-8, 12"value={customStr}onChange={e=>setCustomStr(e.target.value)}/>
          <div style={{fontSize:11,color:G.text3,marginTop:6,lineHeight:1.7}}>
            Enter individual pages and/or ranges separated by commas.<br/>
            <span style={{color:G.text2}}>Examples: </span>
            <span style={{color:G.green,fontFamily:'monospace'}}>2, 5, 9</span>
            <span style={{color:G.text3}}> or </span>
            <span style={{color:G.green,fontFamily:'monospace'}}>1-4, 7, 10-15</span>
            <span style={{color:G.text3}}> or </span>
            <span style={{color:G.green,fontFamily:'monospace'}}>3-3</span>
          </div>
          {(()=>{
            if(!customStr.trim())return null;
            const{pages,err}=parseCustom(customStr);
            if(err||pages.length===0)return null;
            return(<div style={{background:G.greenBg,border:`1px solid ${G.greenBdr}`,borderRadius:8,padding:'8px 12px',marginTop:8,fontSize:12}}>
              <span style={{color:'#4ADE80',fontWeight:700}}>{pages.length} page{pages.length>1?'s':''} selected: </span>
              <span style={{color:G.green,fontFamily:'monospace'}}>{pages.length<=20?pages.join(', '):pages.slice(0,20).join(', ')+` … +${pages.length-20} more`}</span>
            </div>);
          })()}
        </div>
      )}

      {parseErr&&(<div style={{...css.err,marginTop:8,fontSize:12}}>⚠ {parseErr}</div>)}
    </div>
  );
}

// ── NEW JOB ───────────────────────────────────────────────────────────────────
function NewJobScreen({onNav,uploadedFile}){
  const[shops,setShops]=useState([]);const[shopId,setShopId]=useState('');
  const[colorMode,setColorMode]=useState('bw');const[paperSize,setPaperSize]=useState('A4');
  const[copies,setCopies]=useState(1);const[doubleSided,setDoubleSided]=useState(false);
  const[resolvedPages,setResolvedPages]=useState(1);const[pageDescriptor,setPageDescriptor]=useState('all');
  const[amount,setAmount]=useState(0);const[loading,setLoading]=useState(false);const[err,setErr]=useState('');
  const fileName=uploadedFile?.name||'document.pdf';

  useEffect(()=>{api.get('/shops/nearby/').then(r=>setShops(r.data.shops||[])).catch(()=>{});},[]);
  useEffect(()=>{const RATES={bw:{A4:1.5,A3:2.25,Letter:1.5},color:{A4:7,A3:10.5,Letter:7}};const rate=(RATES[colorMode]||RATES.bw)[paperSize]||1.5;const pages=resolvedPages>0?resolvedPages:1;setAmount(+(rate*pages*copies*(doubleSided?0.8:1)).toFixed(2));},[resolvedPages,colorMode,paperSize,copies,doubleSided]);
  const handlePagesChange=useCallback((count,descriptor)=>{setResolvedPages(count);setPageDescriptor(descriptor);},[]);

  const submit=async()=>{
    if(!shopId){setErr('Please select a shop');return;}
    if(!pageDescriptor){setErr('Please complete the page selection');return;}
    if(resolvedPages<1){setErr('Page selection is invalid');return;}
    setLoading(true);setErr('');
    try{
      if(uploadedFile){const fd=new FormData();fd.append('file',uploadedFile);fd.append('shop_id',shopId);fd.append('file_name',fileName);fd.append('pages',resolvedPages);fd.append('page_descriptor',pageDescriptor);fd.append('color_mode',colorMode);fd.append('paper_size',paperSize);fd.append('copies',copies);fd.append('double_sided',doubleSided);await api.post('/jobs/create/',fd,{headers:{'Content-Type':'multipart/form-data'}});}
      else{await api.post('/jobs/create/',{shop_id:shopId,file_name:fileName,pages:resolvedPages,page_descriptor:pageDescriptor,color_mode:colorMode,paper_size:paperSize,copies,double_sided:doubleSided});}
      onNav('jobs');
    }catch(e){setErr(e.response?.data?.error||'Failed to create job');}finally{setLoading(false);}
  };

  const canSubmit=shopId&&pageDescriptor&&resolvedPages>=1;
  return(
    <div style={css.page}>
      <BackBtn onClick={()=>onNav('upload')}/>
      <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:24}}><div style={{display:'flex',alignItems:'center',gap:6}}><div style={{width:26,height:26,borderRadius:13,background:G.greenBg,border:`1px solid ${G.greenBdr}`,display:'flex',alignItems:'center',justifyContent:'center',fontSize:12,fontWeight:800,color:G.green}}>✓</div><span style={{fontSize:13,color:G.green,fontWeight:600}}>Upload</span></div><div style={{flex:1,height:1,background:G.greenBdr}}/><div style={{display:'flex',alignItems:'center',gap:6}}><div style={{width:26,height:26,borderRadius:13,background:G.greenDark,display:'flex',alignItems:'center',justifyContent:'center',fontSize:12,fontWeight:800,color:'#fff'}}>2</div><span style={{fontSize:13,color:G.text,fontWeight:700}}>Preferences</span></div></div>
      <div style={css.pageTitle}>Print preferences</div>
      <div style={css.col}>
        <div style={{background:'#081A10',border:`1px solid ${G.greenBdr}`,borderRadius:12,padding:14,display:'flex',alignItems:'center',gap:12}}><span style={{fontSize:26}}>{getFileIcon(fileName)}</span><div style={{flex:1,overflow:'hidden'}}><div style={{fontWeight:600,color:G.green,fontSize:14,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{fileName}</div>{uploadedFile&&(<div style={{fontSize:11,color:'#4ADE80',marginTop:2}}>{fmtSize(uploadedFile.size)} · Ready to print</div>)}</div><button style={{background:'none',border:`1px solid ${G.border2}`,color:G.text3,cursor:'pointer',fontSize:11,padding:'5px 10px',borderRadius:6,whiteSpace:'nowrap'}}onClick={()=>onNav('upload')}>Change</button></div>
        <div style={css.card}><label style={css.label}>Print shop</label>{shops.length===0?(<div style={{color:G.text3,fontSize:13,padding:'8px 0'}}>No shops online right now</div>):shops.map(s=>(<div key={s.id}onClick={()=>setShopId(s.id)}style={{background:shopId===s.id?G.greenBg:G.card2,border:`1.5px solid ${shopId===s.id?G.green:G.border2}`,borderRadius:10,padding:12,cursor:'pointer',marginBottom:6}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><div style={{fontWeight:700,color:G.text}}>{s.name}</div><span style={{...css.badge,background:s.is_online?G.greenBg:'#1A1A1A',color:s.is_online?G.green:G.text3}}>{s.is_online?'● Online':'○ Offline'}</span></div><div style={{fontSize:12,color:G.text3,marginTop:2}}>{s.address}</div><div style={{display:'flex',justifyContent:'space-between',marginTop:6,fontSize:12}}><span style={{color:s.queue_length>=18?G.red:s.queue_length>=14?G.amber:G.text3}}>Queue: {s.queue_length}/20 {s.queue_length>=20?'· Full 🔴':s.queue_length>=14?'· Busy 🟡':'· Free 🟢'}</span><span style={{color:G.text3}}>⏰ {s.opens_at}–{s.closes_at}</span></div>{shopId===s.id&&<div style={{fontSize:12,color:G.green,marginTop:6,fontWeight:600}}>✓ Selected</div>}</div>))}</div>
        <div style={css.card}>
          <label style={css.label}>Print settings</label>
          <div style={{marginBottom:16}}><div style={{fontSize:12,color:G.text3,marginBottom:8}}>Color mode</div><div style={css.row}><Chip val="bw"cur={colorMode}onSet={setColorMode}label="⬛ Black & White"/><Chip val="color"cur={colorMode}onSet={setColorMode}label="🎨 Color"/></div></div>
          <div style={{marginBottom:16}}><div style={{fontSize:12,color:G.text3,marginBottom:8}}>Paper size</div><div style={css.row}>{['A4','A3','Letter'].map(s=><Chip key={s}val={s}cur={paperSize}onSet={setPaperSize}label={s}/>)}</div></div>

          {/* ── PAGES — PageSelector component ── */}
          <div style={{marginBottom:16}}>
            <div style={{fontSize:12,color:G.text3,marginBottom:10}}>Pages to print</div>
            <PageSelector onPagesChange={handlePagesChange}/>
          </div>

          <div style={{marginBottom:16}}><div style={{fontSize:12,color:G.text3,marginBottom:8}}>Copies</div><div style={{display:'flex',alignItems:'center',gap:16}}><button style={{width:40,height:40,borderRadius:20,background:G.card2,border:`1px solid ${G.border2}`,color:G.text,cursor:'pointer',fontSize:22,display:'flex',alignItems:'center',justifyContent:'center'}}onClick={()=>setCopies(c=>Math.max(1,c-1))}>−</button><span style={{fontSize:22,fontWeight:800,color:G.text,minWidth:40,textAlign:'center'}}>{copies}</span><button style={{width:40,height:40,borderRadius:20,background:G.card2,border:`1px solid ${G.border2}`,color:G.text,cursor:'pointer',fontSize:22,display:'flex',alignItems:'center',justifyContent:'center'}}onClick={()=>setCopies(c=>Math.min(50,c+1))}>+</button></div></div>
          <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',background:G.card2,padding:14,borderRadius:10}}><div><div style={{fontWeight:600,color:G.text,fontSize:14}}>Double-sided</div><div style={{fontSize:12,color:G.text3}}>Saves 20% on printing cost</div></div><div onClick={()=>setDoubleSided(d=>!d)}style={{width:48,height:26,borderRadius:13,background:doubleSided?G.greenDark:G.card2,border:`1px solid ${doubleSided?G.green:G.border2}`,position:'relative',cursor:'pointer'}}><div style={{position:'absolute',top:3,left:doubleSided?22:3,width:20,height:20,borderRadius:10,background:'#fff',transition:'left 0.2s'}}/></div></div>
        </div>
        <div style={{background:G.greenBg,border:`1px solid ${G.greenBdr}`,borderRadius:14,padding:20,textAlign:'center'}}><div style={{fontSize:12,color:'#4ADE80',marginBottom:4}}>Estimated total</div><div style={{fontSize:42,fontWeight:900,color:G.green}}>₹{amount}</div><div style={{fontSize:12,color:'#4ADE80',marginTop:6}}>{resolvedPages>0?`${resolvedPages} page${resolvedPages>1?'s':''}`:pageDescriptor==='all'?'All pages':'Select pages above'}{resolvedPages>0?` · ${copies} ${copies===1?'copy':'copies'} · ${colorMode==='color'?'Color':'B&W'}${doubleSided?' · duplex':''}`:''}</div></div>
        <Alert msg={err}/>
        <button style={{...css.btn,opacity:loading||!canSubmit?0.5:1}}onClick={submit}disabled={loading||!canSubmit}>{loading?'Creating job…':'Create job →'}</button>
      </div>
    </div>
  );
}

function ShopsScreen(){const[shops,setShops]=useState([]);const[loading,setLoading]=useState(true);useEffect(()=>{api.get('/shops/nearby/').then(r=>setShops(r.data.shops||[])).finally(()=>setLoading(false));},[]);return(<div style={css.page}><div style={css.pageTitle}>Shops near me</div>{loading?<Spinner/>:shops.length===0?(<div style={{textAlign:'center',padding:60,color:G.text3}}><div style={{fontSize:48}}>📍</div><div style={{fontSize:14,marginTop:12}}>No shops online right now</div></div>):shops.map(s=>(<div key={s.id}style={{...css.card,marginBottom:8}}><div style={{display:'flex',alignItems:'center',justifyContent:'space-between'}}><div style={{fontWeight:700,color:G.text,fontSize:15}}>{s.name}</div><span style={{...css.badge,background:s.is_online?G.greenBg:'#1A1A1A',color:s.is_online?G.green:G.text3}}>{s.is_online?'● Online':'○ Offline'}</span></div><div style={{fontSize:13,color:G.text3,marginTop:4}}>{s.address}</div><div style={{display:'flex',justifyContent:'space-between',marginTop:8,fontSize:12,color:G.text3}}><span>⏰ {s.opens_at} – {s.closes_at}</span><span style={{color:s.queue_length>=20?G.red:s.queue_length>=14?G.amber:G.text3}}>Queue: {s.queue_length}/20</span></div></div>))}</div>);}

function PickupIDScreen({user,onBack}){return(<div style={css.page}><BackBtn onClick={onBack}/><div style={{fontSize:22,fontWeight:800,color:G.text,textAlign:'center',marginBottom:24}}>Show at the counter</div><div style={{background:G.greenBg,border:`1px solid ${G.greenBdr}`,borderRadius:20,padding:40,textAlign:'center',marginBottom:12}}><div style={{fontSize:13,color:'#4ADE80',marginBottom:12}}>YOUR PRINTSHOP ID</div><div style={{fontSize:72,fontWeight:900,color:G.green,letterSpacing:12}}>{user.short_id}</div><div style={{fontSize:15,color:'#4ADE80',marginTop:10}}>{user.name}</div></div><div style={{background:G.purpleBg,border:`1px solid ${G.purpleBdr}`,borderRadius:16,padding:24,textAlign:'center',marginBottom:20}}><div style={{fontSize:11,color:'#A78BFA',marginBottom:8}}>YOUR PICKUP CODE (say this to shopkeeper)</div><div style={{fontSize:48,fontWeight:900,color:G.purple,letterSpacing:10}}>{user.pickup_code}</div></div><div style={css.card}><div style={{fontSize:11,fontWeight:700,color:G.text3,textTransform:'uppercase',letterSpacing:0.8,marginBottom:14}}>How pickup works</div>{['Tell the shopkeeper your ID (e.g. A123)','They search and find your ready jobs','They ask: "What\'s your 6-digit code?"','Say your code — they type it in','Green light → collect your printout'].map((t,i)=>(<div key={i}style={{display:'flex',gap:10,marginBottom:12,alignItems:'flex-start'}}><div style={{width:22,height:22,borderRadius:11,background:G.greenBg,border:`1px solid ${G.greenBdr}`,display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,fontWeight:800,color:G.green,flexShrink:0}}>{i+1}</div><div style={{fontSize:14,color:G.text2,lineHeight:1.5}}>{t}</div></div>))}</div></div>);}

function ProfileScreen({user,onLogout,onNav}){return(<div style={css.page}><div style={css.pageTitle}>Profile</div><div style={{...css.card,textAlign:'center',marginBottom:12}}><div style={{width:64,height:64,borderRadius:32,background:G.greenBg,border:`1px solid ${G.greenBdr}`,display:'flex',alignItems:'center',justifyContent:'center',fontSize:24,fontWeight:900,color:G.green,margin:'0 auto 12px'}}>{user.name[0].toUpperCase()}</div><div style={{fontSize:20,fontWeight:700,color:G.text}}>{user.name}</div><div style={{fontSize:14,color:G.text3,marginTop:4}}>{user.phone}</div><div style={{display:'inline-flex',gap:6,background:G.greenBg,border:`1px solid ${G.greenBdr}`,borderRadius:20,padding:'6px 16px',marginTop:10}}><span style={{fontSize:12,color:'#4ADE80'}}>ID</span><span style={{fontSize:16,fontWeight:900,color:G.green,letterSpacing:3}}>{user.short_id}</span></div></div>{[{icon:'🪪',title:'My ID card',sub:'Show at counter',action:()=>onNav('pickupid')},{icon:'📋',title:'Print history',sub:'All past jobs',action:()=>onNav('jobs')},{icon:'🚪',title:'Sign out',sub:'',action:onLogout,red:true}].map((item,i)=>(<div key={i}style={{...css.card,display:'flex',alignItems:'center',gap:14,marginBottom:8,cursor:'pointer',borderColor:item.red?'#2D0A0A':G.border}}onClick={item.action}><div style={{width:42,height:42,borderRadius:10,background:item.red?'#200A0A':G.card2,display:'flex',alignItems:'center',justifyContent:'center',fontSize:20}}>{item.icon}</div><div style={{flex:1}}><div style={{fontSize:15,fontWeight:600,color:item.red?G.red:G.text}}>{item.title}</div>{item.sub&&<div style={{fontSize:12,color:G.text3,marginTop:2}}>{item.sub}</div>}</div>{!item.red&&<span style={{color:G.text3}}>→</span>}</div>))}</div>);}

export default function App(){
  const[user,setUser]=useState(()=>{try{return JSON.parse(localStorage.getItem('user')||'null');}catch{return null;}});
  const[page,setPage]=useState('login');const[tab,setTab]=useState('home');const[uploadedFile,setUploadedFile]=useState(null);
  useEffect(()=>{if(localStorage.getItem('token')&&user)setPage('app');},[]);
  const handleLogin=(u)=>{setUser(u);setPage('app');setTab('home');};
  const handleLogout=()=>{localStorage.clear();setUser(null);setPage('login');};
  const navigate=useCallback((dest)=>setTab(dest),[]);
  const handleFileReady=useCallback((f)=>setUploadedFile(f),[]);
  if(page==='login')return <div style={css.app}><LoginScreen onLogin={handleLogin}onGoRegister={()=>setPage('register')}/></div>;
  if(page==='register')return <div style={css.app}><RegisterScreen onLogin={handleLogin}onGoLogin={()=>setPage('login')}/></div>;
  const renderTab=()=>{if(tab==='upload')return<UploadScreen onNav={navigate}onFileReady={handleFileReady}/>;if(tab==='newjob')return<NewJobScreen onNav={navigate}uploadedFile={uploadedFile}/>;if(tab==='pickupid')return<PickupIDScreen user={user}onBack={()=>setTab('home')}/>;if(tab==='jobs')return<JobsScreen onNav={navigate}/>;if(tab==='shops')return<ShopsScreen/>;if(tab==='profile')return<ProfileScreen user={user}onLogout={handleLogout}onNav={navigate}/>;return<HomeScreen user={user}onNav={navigate}/>;};
  const mainTabs=['home','jobs','shops','profile'];
  return(<div style={css.app}><div style={css.nav}><div style={css.navBrand}>🖨️ PrintShop</div><div style={css.navRight}><div style={{fontSize:13,color:G.text3}}>{user.name.split(' ')[0]}</div><div style={{width:32,height:32,borderRadius:16,background:G.greenBg,display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,fontWeight:800,color:G.green,cursor:'pointer'}}onClick={()=>navigate('profile')}>{user.name[0].toUpperCase()}</div></div></div>{renderTab()}{mainTabs.includes(tab)&&<TabBar active={tab}onNav={navigate}/>}</div>);
}
